function render(){document.documentElement.lang=state.lang;document.getElementById('sideNav').innerHTML=['home','schedule','money','settings'].map(nav).join('');document.getElementById('bottomNav').innerHTML=['home','schedule','money','settings'].map(nav).join('');document.querySelector('[data-i18n=localOnly]').textContent=t('localOnly');document.getElementById('headerDate').textContent=longDate(localDate());document.getElementById('headerSettings').title=t('settings');document.querySelector('#voiceFab').setAttribute('aria-label',t('talkNow'));document.title=`AI IA — ${t(page)}`;document.getElementById('content').innerHTML=({home:renderHome,schedule:renderSchedule,money:renderMoney,settings:renderSettings}[page])();}
function empty(title,desc,ic='calendar'){return `<div class="empty">${icon(ic)}<strong>${e(title)}</strong>${desc?`<span>${e(desc)}</span>`:''}</div>`}
const taskCard=(x,mini=false)=>`<article class="task-card ${x.status==='done'?'complete':''} ${x.status==='cancelled'?'complete':''}"><div class="time-badge">${x.time?e(x.time):`<span class="no-time-label">${e(vw('noTime'))}</span>`}</div><div class="task-data"><strong>${e(x.title)}</strong><small>${icon('pin')}${e(x.address||t('noLocation'))}</small>${x.boiler?`<small>${e(ux('boiler'))}: ${e(x.boiler)}</small>`:''}${x.errorCode?`<small>${e(ux('errorCode'))}: ${e(x.errorCode)}</small>`:''}${Number(x.expectedAmount)>0?`<small>${e(ux(x.paymentStatus==='paid'?'received':'expected'))}: ${e(amountFmt(x.expectedAmount,x.amountCurrency||'GEL'))}</small>`:''}${x.status==='cancelled'?`<small>${e(ux('cancelled'))}</small>`:''}${!mini&&x.phone?`<small>${icon('phone')}${e(x.phone)}</small>`:''}</div><div class="task-actions">${x.address?`<button class="micro-btn" data-action="maps" data-id="${e(x.id)}" title="${t('map')}">${icon('pin')}</button>`:''}${x.status==='active'&&Number(x.expectedAmount)>0&&x.paymentStatus!=='paid'?`<button class="micro-btn" data-action="mark-task-paid" data-id="${e(x.id)}" title="${e(ux('receivedButton'))}">${icon('wallet')}</button>`:''}<button class="micro-btn" data-action="toggle-task" data-id="${e(x.id)}" title="${x.status==='done'?t('reopen'):t('done')}">${icon('check')}</button>${!mini?`<button class="micro-btn" data-action="edit-task" data-id="${e(x.id)}" title="${t('edit')}">${icon('edit')}</button>`:''}</div></article>`;
const moneyRow=(x,editable=false)=>`<div class="money-row"><span class="money-ico ${x.type}">${icon(x.type==='income'?'arrowdown':'arrowup')}</span><div class="money-details"><strong>${e(x.description||t(x.category)||t('other'))}</strong><small>${e(shortDate(x.date))} · ${e(t(x.category))} · ${e(t((x.scope||'work')==='personal'?'categoryPersonal':'categoryWork'))}</small></div><div class="money-value ${x.type}">${x.type==='income'?'+':'−'}${e(amountFmt(x.amount,x.currency))}</div>${editable?`<button class="micro-btn" data-action="edit-money" data-id="${e(x.id)}" title="${t('edit')}">${icon('edit')}</button>`:''}</div>`;
function todayAddressCard(x){return `<article class="today-address-card"><div class="today-time">${x.time?e(x.time):`<span class="no-time-label">${e(vw('noTime'))}</span>`}</div><div class="today-place"><strong>${icon('pin')}${e(x.address||t('noLocation'))}</strong><span>${e(x.title)}${x.boiler?' · '+e(x.boiler):''}${x.errorCode?' · '+e(x.errorCode):''}${Number(x.expectedAmount)>0?' · '+e(amountFmt(x.expectedAmount,x.amountCurrency||'GEL')):''}</span></div><div class="today-buttons">${x.address?`<button class="secondary-btn" data-action="maps" data-id="${e(x.id)}">${icon('pin')}${tt('openMaps')}</button>`:''}<button class="micro-btn" data-action="edit-task" data-id="${e(x.id)}" title="${t('edit')}">${icon('edit')}</button><button class="micro-btn" data-action="toggle-task" data-id="${e(x.id)}" title="${t('done')}">${icon('check')}</button></div></article>`}
function renderHome(){const today=dayTasks();return `<section class="page">
<div class="panel today-primary"><div class="panel-heading"><div><div class="eyebrow">${e(longDate(localDate()))}</div><h2>${tt('todayAddresses')}</h2><p class="today-subtitle">${tt('todayAddressesSub')}</p></div><button class="text-link" data-action="navigate" data-page="schedule">${t('seeAll')} →</button></div><div class="today-address-list">${today.length?today.map(todayAddressCard).join(''):empty(tt('emptyTodayAddresses'),t('noTasksDesc'),'pin')}</div><button class="secondary-btn" style="width:100%;margin-top:14px" data-action="add-task">${icon('plus')}${t('addTask')}</button></div>
<div class="hero" style="margin-top:22px"><div><div class="eyebrow">${t('eyebrow')}</div><h1>${t('hello')}</h1><p>${t('heroSub')}</p></div><div class="hero-graphic"><span>ia<i>.</i></span></div></div>
<div class="overview"><div class="metric"><div class="metric-top"><span class="metric-label">${t('todayTasks')}</span><span class="metric-icon">${icon('calendar')}</span></div><strong>${today.length}</strong><div class="metric-caption">${t('plannedToday')}</div></div><div class="metric positive"><div class="metric-top"><span class="metric-label">${t('todayIncome')}</span><span class="metric-icon">${icon('arrowdown')}</span></div><strong>${e(amountFmt(todayMoney('income')))}</strong><div class="metric-caption">${t('incomeToday')}</div></div><div class="metric negative"><div class="metric-top"><span class="metric-label">${t('todayExpense')}</span><span class="metric-icon">${icon('arrowup')}</span></div><strong>${e(amountFmt(todayMoney('expense')))}</strong><div class="metric-caption">${t('expenseToday')}</div></div></div>
<div class="dashboard-grid"><div class="panel assistant-panel"><div class="panel-heading"><h2>${t('sayHi')}</h2><span class="tag">AI IA</span></div><div class="assistant-body"><div class="orb">${icon('mic')}</div><h3>${t('voiceTitle')}</h3><p>${t('assistantSub')}</p><button class="primary-btn" data-action="voice">${icon('mic')}${t('talkNow')}</button><div class="assistant-tip">${icon('light')}<span>${t('voiceExample')}</span></div></div></div><div class="panel"><div class="panel-heading"><h2>${tt('monthReport')}</h2><button class="text-link" data-action="open-month-report">${t('seeAll')} →</button></div>${monthlySummaryCards()}<button class="secondary-btn" data-action="open-month-report" style="width:100%;margin-top:15px">${icon('wallet')}${tt('monthReport')}</button></div></div>
</section>`;}
function monthTransactions(){return state.transactions.filter(x=>x.date.slice(0,7)===reportMonth&&x.currency===state.currency&&(scopeFilter==='all'||(x.scope||'work')===scopeFilter));}
function monthlySummaryCards(){let tx=monthTransactions(),inc=tx.filter(x=>x.type==='income').reduce((n,x)=>n+Number(x.amount),0),exp=tx.filter(x=>x.type==='expense').reduce((n,x)=>n+Number(x.amount),0);return `<div class="monthly-stats"><div><span>${t('income')}</span><strong class="text-success">${e(amountFmt(inc))}</strong></div><div><span>${t('expense')}</span><strong class="text-expense">${e(amountFmt(exp))}</strong></div><div><span>${t('myBalance')}</span><strong>${e(amountFmt(inc-exp))}</strong></div></div>`}
function pendingMoney(){const items=state.tasks.filter(x=>x.status!=='cancelled'&&Number(x.expectedAmount)>0&&x.paymentStatus!=='paid'&&(scopeFilter==='all'||scopeFilter==='work')&&x.date.slice(0,7)===reportMonth&&(x.amountCurrency||'GEL')===state.currency);return items.reduce((sum,x)=>sum+Number(x.expectedAmount),0)}
function monthlyBreakdown(){let entries=monthTransactions().filter(x=>x.type==='expense'),categories={};for(const x of entries)categories[x.category||'other']=(categories[x.category||'other']||0)+Number(x.amount);let rows=Object.entries(categories).sort((a,b)=>b[1]-a[1]);const biggest=Math.max(1,...rows.map(x=>x[1]));return `<div class="breakdown">${rows.length?rows.map(([cat,total])=>`<div class="breakdown-row"><div class="breakdown-label"><strong>${e(t(cat))}</strong><span>${e(amountFmt(total))}</span></div><div class="bar-track"><div style="width:${Math.min(100,total/biggest*100).toFixed(2)}%"></div></div></div>`).join(''):empty(tt('noBreakdown'),'','wallet')}</div>`}
function renderSchedule(){const now=new Date();let tasks=state.tasks.filter(x=>scheduleFilter==='all'||(scheduleFilter==='completed'?(x.status==='done'||x.status==='cancelled'):x.status==='active'&&(x.time?new Date(dateTimeLocal(x)).getTime()>=new Date(now.getTime()-86400000).getTime():x.date>=localDate())));tasks.sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));let grouped={};for(const x of tasks)(grouped[x.date]??=[]).push(x);return `<section class="page"><div class="section-header"><div><div class="eyebrow">AI IA</div><h1>${t('schedule')}</h1><p>${t('upcoming')}</p></div><button class="primary-btn" data-action="add-task">${icon('plus')}${t('addTask')}</button></div><div class="filters">${[['upcoming','upcomingFilter'],['all','all'],['completed','completed']].map(([id,label])=>`<button class="chip ${scheduleFilter===id?'active':''}" data-action="filter-schedule" data-filter="${id}">${t(label)}</button>`).join('')}</div><div class="panel"><div class="all-items">${tasks.length?Object.entries(grouped).map(([date,items])=>`<div class="date-label">${e(longDate(date))}</div>${items.map(x=>taskCard(x)).join('')}`).join(''):empty(t('noResults'),t('noTasksDesc'))}</div></div></section>`;}
function debtItem(x){return `<div class="debt-item"><div class="money-ico ${x.direction==='receivable'?'income':'expense'}">${icon(x.direction==='receivable'?'arrowdown':'arrowup')}</div><div class="debt-info"><strong>${e(x.person||t(x.direction))}</strong><small>${e(t(x.direction))}${x.dueDate?' · '+e(shortDate(x.dueDate)):''} · ${x.status==='settled'?t('settled'):t('active')}</small></div><div class="debt-amount">${e(amountFmt(x.amount,x.currency))}</div>${x.status!=='settled'?`<button class="micro-btn" data-action="settle-debt" data-id="${e(x.id)}" title="${t('markSettled')}">${icon('check')}</button>`:''}<button class="micro-btn" data-action="edit-debt" data-id="${e(x.id)}" title="${t('edit')}">${icon('edit')}</button></div>`}
function renderMoney(){let inc=groupedMoney('income'),exp=groupedMoney('expense'),tx=[...state.transactions].filter(x=>(scopeFilter==='all'||(x.scope||'work')===scopeFilter)&&(moneyFilter==='all'||x.date.slice(0,7)===reportMonth)).sort((a,b)=>(b.date+b.createdAt).localeCompare(a.date+a.createdAt)),debt=state.debts.filter(x=>showDebt==='all'||x.status==='active').sort((a,b)=>String(a.dueDate||'9999').localeCompare(String(b.dueDate||'9999')));return `<section class="page"><div class="section-header"><div><div class="eyebrow">AI IA</div><h1>${t('money')}</h1><p>${t('incomeExpense')}</p></div><div class="section-actions"><select class="currency-select" id="dashboardCurrency" aria-label="${t('currency')}">${['GEL','USD','EUR'].map(c=>`<option ${state.currency===c?'selected':''}>${c}</option>`).join('')}</select><button class="primary-btn" data-action="add-money">${icon('plus')}${t('addMoney')}</button></div></div><div class="filters">${[['month','month'],['all','allTime']].map(([f,l])=>`<button class="chip ${moneyFilter===f?'active':''}" data-action="filter-money" data-filter="${f}">${t(l)}</button>`).join('')}</div><div class="filters">${[['all','all'],['work','categoryWork'],['personal','categoryPersonal']].map(([f,l])=>`<button class="chip ${scopeFilter===f?'active':''}" data-action="filter-scope" data-filter="${f}">${t(l)}</button>`).join('')}</div><div class="panel monthly-report" id="monthlyReport"><div class="panel-heading"><h2>${tt('monthReport')}</h2><label class="month-selector">${tt('chooseMonth')} <input id="reportMonth" type="month" value="${e(reportMonth)}"></label></div>${monthlySummaryCards()}<p class="hint">${ux('forecast')}: <strong>${e(amountFmt(pendingMoney()))}</strong></p><h3>${tt('spendingBreakdown')}</h3>${monthlyBreakdown()}<p class="hint">${tt('monthlyReportTip')}</p></div><div class="overview"><div class="metric positive"><span class="metric-label">${t('income')}</span><strong>${e(amountFmt(inc))}</strong></div><div class="metric negative"><span class="metric-label">${t('expense')}</span><strong>${e(amountFmt(exp))}</strong></div><div class="metric"><span class="metric-label">${t('myBalance')}</span><strong>${e(amountFmt(inc-exp))}</strong><div class="metric-caption">${t('balanceNote')}</div></div></div><p class="hint">${t('financialHint')}</p><div class="lower-grid"><div class="panel"><div class="panel-heading"><h2>${t('moneyHistory')}</h2><span class="tag">${tx.length}</span></div>${tx.length?`<div class="money-list">${tx.map(x=>moneyRow(x,true)).join('')}</div>`:empty(t('noMoney'),t('noMoneyDesc'),'wallet')}</div><div class="panel"><div class="panel-heading"><h2>${t('debts')}</h2><button class="text-link" data-action="add-debt">+ ${t('addDebt')}</button></div><div class="filters"><button class="chip ${showDebt==='active'?'active':''}" data-action="filter-debt" data-filter="active">${t('active')}</button><button class="chip ${showDebt==='all'?'active':''}" data-action="filter-debt" data-filter="all">${t('all')}</button></div>${debt.length?`<div>${debt.map(debtItem).join('')}</div>`:empty(t('noDebts'),'','wallet')}</div></div></section>`;}
function renderSettings(){return `<section class="page"><div class="section-header"><div><div class="eyebrow">AI IA</div><h1>${t('settings')}</h1><p>${t('localOnly')}</p></div></div><div class="settings-grid"><div class="panel"><h2>${t('chooseLanguage')}</h2><p>${t('languageDesc')}</p><div class="field"><select id="languageChoice" aria-label="${t('chooseLanguage')}"><option value="ka" ${state.lang==='ka'?'selected':''}>ქართული</option><option value="en" ${state.lang==='en'?'selected':''}>English</option><option value="ru" ${state.lang==='ru'?'selected':''}>Русский</option></select></div></div><div class="panel"><h2>${t('defaultCurrency')}</h2><p>${t('defaultCurrencyDesc')}</p><div class="field"><select id="currencyChoice" aria-label="${t('currency')}">${['GEL','USD','EUR'].map(c=>`<option ${state.currency===c?'selected':''}>${c}</option>`).join('')}</select></div></div><div class="panel"><h2>${t('dataTitle')}</h2><p>${t('dataDesc')}</p><div class="settings-actions"><button class="secondary-btn" data-action="export">${icon('download')}${t('export')}</button><button class="outline-btn" data-action="import">${icon('upload')}${t('import')}</button></div><input type="file" id="importFile" accept=".json,application/json" hidden><p class="hint">${t('storageNote')}</p><button class="text-link" style="color:#ff9aaf" data-action="clear">${t('deleteAll')}</button></div><div class="panel"><h2>${t('notifications')}</h2><p>${t('notificationsDesc')}</p><button class="secondary-btn" data-action="notifications">${icon('bell')}${t('enableNotifications')}</button><p class="hint">${t('prototypeDesc')}</p></div></div><div class="panel spaced"><div class="eyebrow">AI IA · 0.5</div><h2>${t('prototype')}</h2><p class="muted">${t('prototypeDesc')}</p></div></section>`;}
function modal(title,body,foot=''){document.getElementById('modalRoot').innerHTML=`<div class="modal-overlay" data-action="backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="${e(title)}"><div class="modal-head"><h2>${e(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="${t('cancel')}">${icon('close')}</button></div>${body}${foot}</div></div>`;const el=document.querySelector('.modal input:not([type=hidden]),.modal textarea,.modal button.voice-button');el?.focus();}
